<script lang="ts">
 import {invalidateAll} from '$app/navigation';let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();let pack=$state(''),lot=$state(''),uploaded=$state<any>(null),ack=$state(false),busy=$state(false),message=$state('');
 async function file(event:Event){const f=(event.currentTarget as HTMLInputElement).files?.[0];if(!f||f.size>1000000)return;try{uploaded=JSON.parse(await f.text());}catch{message=t('INVALID_JSON');}}
 async function submit(action:string){busy=true;try{const res=await fetch('/api/rules',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(action==='create'?{...uploaded,action,review_acknowledged:ack}:{action,rule_set_id:pack,lot_id:lot})});message=res.ok?t('saved'):t((await res.json()).message);if(res.ok)await invalidateAll();}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
</script>
<section class="card"><h2>{t('rule_sets')}</h2><p class="muted">{t('rulesHint')}</p><form onsubmit={(e)=>{e.preventDefault();submit('check');}}><div class="grid"><label>{t('rule_sets')}<select bind:value={pack} required><option value="">—</option>{#each model.rule_sets as r}<option value={r.id}>{r.name} · {r.jurisdiction} · {r.valid_from}–{r.valid_to}</option>{/each}</select></label><label>{t('lot_id')}<select bind:value={lot} required><option value="">—</option>{#each model.lots as l}<option value={l.id}>{l.code}</option>{/each}</select></label></div><button disabled={busy}>{t('checkRules')}</button></form><details><summary>{t('importRulePack')}</summary><a href="/rule-pack-example.json" download>{t('ruleExample')}</a><label>JSON<input type="file" accept=".json" onchange={file} /></label>{#if uploaded}<pre>{JSON.stringify(uploaded,null,2)}</pre><label class="check"><input type="checkbox" bind:checked={ack} />{t('reviewRulePack')}</label><button onclick={()=>submit('create')} disabled={busy||!ack}>{t('save')}</button>{/if}</details><p role="status">{message}</p></section>
<style>.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:15px 0}pre{overflow:auto;max-height:350px;font-size:11px}.check{display:flex;align-items:center;margin:20px 0}.check input{width:18px;height:18px}summary{margin:20px 0}</style>
